THOUGHT: E.6 requires richer message rows and interactive toolbars, threads, edits, deletes, and emoji reactions while preserving E.5. I’ll extend the message renderer and handlers in one replacement, using the existing REST routes and stable pinned test IDs.

```mswea_bash_command
python3 - <<'PY'
p='/app/static/app.js';s=open(p).read()
start=s.index('async function selectChannel(');end=s.index('\nasync function createWorkspace',start)
new=r'''async function selectChannel(c){if(state.workspace){try{let fresh=await api('GET','/workspaces/'+state.workspace.slug);let found=(fresh.channels||[]).find(x=>String(x.id)===String(c.id));if(found)c=found}catch(e){}}state.channel=c;text('channel-title','#'+c.name);text('channel-topic',c.topic||'');let x=await api('GET','/channels/'+c.id+'/messages');let l=document.getElementById('message-list');l.innerHTML='';let ms=(x.messages||[]).reverse();show('channel-empty-state',!ms.length);if(!ms.length)text('channel-empty-state','No messages yet. Start the conversation.');ms.forEach(renderMessage)}
function renderMessage(m){let d=document.createElement('div');d.className='message';d.dataset.testid='message';d.dataset.messageId=m.id;let author=(m.author||{}).display_name||'User';d.innerHTML='<span data-testid="message-avatar">●</span> <b data-testid="message-author">'+author+'</b> <small data-testid="message-time">'+new Date(m.created_at||Date.now()).toLocaleString()+'</small><div data-testid="message-body"></div><span data-testid="message-edited">'+(m.edited_at?'edited':'')+'</span><span data-testid="reply-count">'+(m.reply_count?(m.reply_count+' '+(m.reply_count===1?'reply':'replies'):'')+'</span><div class="toolbar"><button data-testid="edit-message-btn">Edit</button><button data-testid="delete-message-btn">Delete</button><button data-testid="open-thread-btn">Thread</button><button data-testid="reaction-button">☺</button></div><div class="reaction-chips"></div>';d.querySelector('[data-testid=message-body]').textContent=m.body;d.querySelector('[data-testid=edit-message-btn]').onclick=()=>editRow(d,m);d.querySelector('[data-testid=delete-message-btn]').onclick=async()=>{await api('DELETE','/messages/'+m.id);d.remove()};d.querySelector('[data-testid=open-thread-btn]').onclick=()=>openThread(m);d.querySelector('[data-testid=reaction-button]').onclick=()=>picker(d,m);(m.reactions||[]).forEach(x=>chip(d,x));document.getElementById('message-list').appendChild(d)}
function editRow(d,m){let i=document.createElement('input');i.dataset.testid='edit-message-input';i.value=d.querySelector('[data-testid=message-body]').textContent;d.querySelector('[data-testid=message-body]').replaceWith(i);i.onkeydown=async e=>{if(e.key==='Enter'){let x=await api('PATCH','/messages/'+m.id,{body:i.value});i.replaceWith(Object.assign(document.createElement('div'),{textContent:x.message.body,dataset:{testid:'message-body'}}));d.querySelector('[data-testid=message-edited]').textContent='edited'}}}
async function openThread(m){show('thread-panel',true);let x=await api('GET','/messages/'+m.id+'/replies');let a=document.getElementById('thread-messages');a.innerHTML='';(x.replies||[]).forEach(renderThread)}
function renderThread(m){let d=document.createElement('div');d.textContent=m.body;document.getElementById('thread-messages').appendChild(d)}
function chip(d,r){let c=document.createElement('span');c.dataset.testid='reaction-chip';c.textContent=r.emoji+' '+r.count;d.querySelector('.reaction-chips').appendChild(c)}
async function picker(d,m){let p=document.getElementById('emoji-picker');if(!p){p=document.createElement('div');p.id='emoji-picker';p.dataset.testid='emoji-picker';document.body.appendChild(p)}p.innerHTML='';['😀','👍','❤️','🎉','🚀','😂'].forEach(e=>{let b=document.createElement('button');b.dataset.testid='emoji-option';b.textContent=e;b.onclick=async()=>{let x=await api('POST','/messages/'+m.id+'/reactions',{emoji:e});p.remove();(x.reactions||[]).forEach(r=>chip(d,r))};p.appendChild(b)})}
async function sendThread(){let i=document.getElementById('thread-input');if(!i.value.trim()||!state.thread)return;let x=await api('POST','/channels/'+state.channel.id+'/messages',{body:i.value,parent_id:state.thread.id});renderThread(x.message);i.value='';state.thread.reply_count=(state.thread.reply_count||0)+1}
'''
s=s[:start]+new+s[end:]
s=s.replace("function init(){", "function init(){state.thread=null;document.getElementById('thread-send').addEventListener('click',sendThread);document.getElementById('close-thread').addEventListener('click',()=>show('thread-panel',false));")
s=s.replace("async function openThread(m){show('thread-panel',true);", "async function openThread(m){state.thread=m;show('thread-panel',true);")
open(p,'w').write(s)
PY
bash /spec/common/restart.sh && bash /spec/e/checks/check_e_6.sh
```

